package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.XPathFactory;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.NullPointer;
import org.apache.commons.jxpath.ri.model.PropertyOwnerPointer;
import org.apache.commons.jxpath.ri.model.QName;
import org.apache.commons.jxpath.ri.model.beans.NullPropertyPointer.BadFactoryException;
import org.apache.commons.jxpath.ri.model.beans.NullPropertyPointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import org.apache.commons.jxpath.ri.model.beans.NullPropertyPointer.BadFactoryException; // Assuming internal exception name based on method




public class NullPropertyPointer_createPath_TriageGen2Test {

    private JXPathContext mockContext;
    private XPathFactory mockFactory;
    private QName mockQName;

    @Before
    public void setUp() {
        mockContext = mock(JXPathContext.class);
        mockFactory = mock(XPathFactory.class);
        mockQName = mock(QName.class);
        when(mockContext.getFactory()).thenReturn(mockFactory);
    }

    /**
     * Helper to create a spy of NullPropertyPointer to control isAttribute() behavior
     * since it is likely a protected/internal method used in the logic.
     */
    private NullPropertyPointer createSpyNullPropertyPointer(NodePointer parent, boolean isAttribute) {
        NullPropertyPointer pointer = new NullPropertyPointer(parent);
        NullPropertyPointer spy = Mockito.spy(pointer);
        when(spy.isAttribute()).thenReturn(isAttribute);
        when(spy.getName()).thenReturn(mockQName);
        return spy;
    }

    @Test
    public void testCreatePath_IsAttribute() {
        NodePointer mockParentPointer = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttributePointer = mock(NodePointer.class);

        NullPropertyPointer spyPointer = createSpyNullPropertyPointer(mockParentPointer, true);

        when(mockParentPointer.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(mockContext, mockQName)).thenReturn(mockAttributePointer);

        NodePointer result = spyPointer.createPath(mockContext);

        assertEquals(mockAttributePointer, result);
    }

    @Test(expected = Exception.class) 
    // Note: createBadFactoryException is protected and likely throws a custom exception.
    // We expect an exception because parent is NullPointer and isAttribute is false.
    public void testCreatePath_ThrowsExceptionWhenParentIsNullPointer() {
        NullPointer nullPointer = new NullPointer();
        NullPropertyPointer spyPointer = createSpyNullPropertyPointer(nullPointer, false);

        // This should trigger: if (parent instanceof NullPointer) throw ...
        spyPointer.createPath(mockContext);
    }

    @Test
    public void testCreatePath_IsPropertyOwnerPointer() {
        NodePointer mockParentPointer = mock(NodePointer.class);
        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);

        NullPropertyPointer spyPointer = createSpyNullPropertyPointer(mockParentPointer, false);

        when(mockParentPointer.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropertyPointer);
        when(mockPropertyPointer.createChild(mockContext, mockQName, 0)).thenReturn(mockChildPointer);

        // We need to ensure getIndex() returns 0 or similar if applicable
        spyPointer.setPropertyIndex(0);

        NodePointer result = spyPointer.createPath(mockContext);

        assertEquals(mockChildPointer, result);
    }

    @Test
    public void testCreatePath_IsRegularNodePointer() {
        NodePointer mockParentPointer = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);

        NullPropertyPointer spyPointer = createSpyNullPropertyPointer(mockParentPointer, false);

        when(mockParentPointer.createPath(mockContext)).thenReturn(mockNewParent);
        // Ensure it's NOT a PropertyOwnerPointer
        when(! (mockNewParent instanceof PropertyOwnerPointer)).thenReturn(true); 
        // (Mocking instanceof is not possible, so we ensure mockNewParent is a standard mock)

        when(mockNewParent.createChild(mockContext, mockQName, 0)).thenReturn(mockChildPointer);
        spyPointer.setPropertyIndex(0);

        NodePointer result = spyPointer.createPath(mockContext);

        assertEquals(mockChildPointer, result);
    }
}
